jq -n --arg dir "$snapshot_dir" \
  --slurpfile threads "$snapshot_dir/review-threads.json" \
  --slurpfile reviews "$snapshot_dir/reviews.json" \
  --slurpfile issues "$snapshot_dir/issue-comments.json" \
  --slurpfile inline "$snapshot_dir/inline-comments.json" \
  --slurpfile pr "$snapshot_dir/pr-view.json" '
  def flatpages($x): ($x[0] | flatten);
  {
    snapshot_dir: $dir,
