        outcome,
        ...(code ? { code } : {}),
        requestId,
        at: (this.options.clock?.() ?? new Date()).toISOString(),
        // Cleanup retries may follow partial release of custom credential state.
        target: phase === "transport-close" ? { kind: "custom" } : this.options.target.describe(),
        ...(details ? { details } : {}),
