  if (
    value && typeof value === "object" &&
    (value as { kind?: unknown }).kind === "mcpfn.official-conformance-report"
  ) {
    const bounded = structuredClone(value) as {
      stdout?: string;
      stderr?: string;
      failure?: { message?: string; details?: unknown };
